// ─── VERIFICATION ────────────────────────────────────────────────────────────

const byMuscle = EXERCISES_SEED.reduce((acc, ex) => {
  for (const m of ex.primary_muscles) {
    acc[m] = (acc[m] || 0) + 1;
  }
  return acc;
}, {} as Record<string, number>);

console.log('Exercise Library Summary:');
console.log(`Total exercises: ${EXERCISES_SEED.length}`);
console.log('\nBy primary muscle group:');
Object.entries(byMuscle).sort((a, b) => b[1] - a[1]).forEach(([m, c]) => {
  console.log(`  ${m.padEnd(20)}: ${c} bài`);
});

const byDifficulty = EXERCISES_SEED.reduce((acc, ex) => {
  acc[ex.difficulty] = (acc[ex.difficulty] || 0) + 1;
  return acc;
}, {} as Record<string, number>);
console.log('\nBy difficulty:');
Object.entries(byDifficulty).forEach(([d, c]) => console.log(`  ${d}: ${c}`));

const byType = EXERCISES_SEED.reduce((acc, ex) => {
  acc[ex.exercise_type] = (acc[ex.exercise_type] || 0) + 1;
  return acc;
}, {} as Record<string, number>);
console.log('\nBy exercise type:');
